    int race(Callable<Boolean> a,Callable<Boolean> b)throws Exception{var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{List<Future<Boolean>> futures=new ArrayList<>();for(var task:List.of(a,b))futures.add(pool.submit(()->{gate.await();try{return task.call();}catch(BusinessException|AccessDeniedException expected){return false;}}));gate.countDown();int passed=0;for(var f:futures)if(f.get(40,TimeUnit.SECONDS))passed++;return passed;}finally{pool.shutdownNow();}}
